package pl.maciek.squashscoreboard;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.*;
public final class SetsChartView extends View{private final MatchRecord r;private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);public SetsChartView(Context c,MatchRecord x){super(c);r=x;}@Override protected void onDraw(Canvas c){float l=dp(42),t=dp(36),rr=getWidth()-dp(16),b=getHeight()-dp(46);ArrayList<int[]>sets=all();int max=1;for(int[]s:sets)max=Math.max(max,Math.max(s[0],s[1]));float step=(rr-l)/Math.max(1,sets.size());p.setTextAlign(Paint.Align.CENTER);for(int i=0;i<sets.size();i++){int[]s=sets.get(i);float cx=l+step*(i+.5f),bar=step*.25f;p.setColor(r.playerOneColor);c.drawRect(cx-bar,b-(b-t)*s[0]/max,cx-dp(2),b,p);p.setColor(r.playerTwoColor);c.drawRect(cx+dp(2),b-(b-t)*s[1]/max,cx+bar,b,p);p.setColor(Color.rgb(174,185,201));p.setTextSize(dp(12));c.drawText("S"+(i+1),cx,b+dp(18),p);c.drawText(s[0]+":"+s[1],cx,t-dp(10),p);}}private ArrayList<int[]>all(){ArrayList<int[]>o=new ArrayList<>();int a=0,z=0;for(int q:r.pointWinners){if(q==1)a++;else z++;if(Math.max(a,z)>=r.pointsToWinSet&&Math.abs(a-z)>=2){o.add(new int[]{a,z});a=0;z=0;}}if(a+z>0)o.add(new int[]{a,z});return o;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}}
